// Pinyin course. Lesson kinds: set = syllables/words [漢字, pinyin, kk, ru]; chart = clickable sound table.
// Chart cell: [label, audio key (a tone-marked syllable), kk hint, ru hint]. Audio keys are spoken with an explicit pinyin phoneme.

// Tone mark on the right vowel: a, else e, else o in "ou", else the last vowel (iu → u, ui → i).
NH.toneMark = (syl, tone) => {
  const M = {a:'āáǎà', e:'ēéěè', i:'īíǐì', o:'ōóǒò', u:'ūúǔù', 'ü':'ǖǘǚǜ'};
  const at = syl.includes('a') ? syl.indexOf('a') : syl.includes('e') ? syl.indexOf('e') : syl.includes('ou') ? syl.indexOf('o')
    : Math.max(...[...'iouü'].map(v => syl.lastIndexOf(v)));
  return syl.slice(0, at) + M[syl[at]][tone - 1] + syl.slice(at + 1);
};
